<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$admin=$auth->requireAdmin();$message='';$selectedApp=(int)($_POST['application_id']??$_GET['application_id']??0);$toolOutput='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);try{$action=(string)($_POST['action']??'diagnose');if($action==='diagnose'){$run=$toolkit->runDiagnostics($selectedApp,(int)$admin['id']);$toolOutput='<h3>Diagnostyka</h3><pre class="code">'.Web::e(json_encode($db->all('SELECT check_name,status,detail FROM integration_diagnostic_checks WHERE run_id=?',[$run]),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre>';}elseif($action==='test_user'){$result=$toolkit->testUser($selectedApp,(int)$_POST['user_id'],['auth_level'=>(int)$_POST['auth_level'],'risk_score'=>(int)$_POST['risk_score'],'country_code'=>(string)$_POST['country_code'],'ip'=>(string)$_POST['ip']]);$toolOutput='<h3>Test User — dry run</h3><pre class="code">'.Web::e(json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)).'</pre>';}elseif($action==='config'){$app=$db->one('SELECT * FROM applications WHERE id=? AND deleted_at IS NULL',[$selectedApp]);if(!$app)throw new RuntimeException('not_found');$snips=$toolkit->snippets($app);$toolOutput='<h3>Konfiguracja bez sekretu</h3><pre class="code">'.Web::e(json_encode($toolkit->configurationPayload($app),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre><h3>QR konfiguracji</h3><div class="qr">'.$toolkit->qrSvg($app).'</div>';foreach($snips as$n=>$code)$toolOutput.='<h4>'.Web::e($n).'</h4><pre class="code">'.Web::e($code).'</pre>';}}catch(Throwable$e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}
$apps=$db->all('SELECT id,name FROM applications WHERE deleted_at IS NULL ORDER BY name');$appOptions='';foreach($apps as$a)$appOptions.='<option value="'.(int)$a['id'].'" '.($selectedApp===(int)$a['id']?'selected':'').'>'.Web::e($a['name']).'</option>';$users=$db->all("SELECT id,name,email FROM users WHERE enabled=1 AND lifecycle_status='active' ORDER BY name LIMIT 500");$userOptions='';foreach($users as$u)$userOptions.='<option value="'.(int)$u['id'].'">'.Web::e($u['name'].' — '.$u['email']).'</option>';$templates='';foreach($toolkit->templates()as$t)$templates.='<tr><td>'.Web::e($t['name']).'</td><td>'.Web::e($t['app_type']).'</td><td>'.Web::e($t['integration_type']).'</td><td>'.Web::e($t['instructions']?:'—').'</td></tr>';
$content='<div class="page-head"><div><h1>Integration diagnostics / Test User</h1><p>Diagnostyka, symulacja polityk, konfiguracja i QR bez ujawniania client secret.</p></div></div>'.$message.'<section class="card"><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Aplikacja<select name="application_id" required>'.$appOptions.'</select></label><div class="actions"><button name="action" value="diagnose">Diagnostyka</button><button name="action" value="config">Config / snippets / QR</button></div><h2>Test User</h2><label>Użytkownik<select name="user_id">'.$userOptions.'</select></label><div class="form-row"><label>Auth level<select name="auth_level"><option>1</option><option>2</option><option>3</option></select></label><label>Risk 0-100<input type="number" name="risk_score" min="0" max="100" value="0"></label><label>Kraj<input name="country_code" maxlength="2" placeholder="PL"></label><label>IP<input name="ip" value="198.51.100.10"></label></div><button class="primary" name="action" value="test_user">Symuluj logowanie</button></form>'.$toolOutput.'</section><div class="table-wrap"><table><thead><tr><th>Szablon</th><th>Typ</th><th>Integracja</th><th>Instrukcja</th></tr></thead><tbody>'.$templates.'</tbody></table></div>';Web::page('Integration tools',$content,$admin);
